import{_ as t,c as e,o as n,a4 as a}from"./chunks/framework.BZK924bi.js";const d=JSON.parse('{"title":"AI资讯日报 2026/3/11","description":"英伟达投资Thinking Machines达500亿美金，LeCun创办AMI种子轮融10.3亿 Figure机器人自主整理客厅，谷歌发布全模态嵌入模型Gemini Embedding 2 MiniMax M2.5开源性价比媲美Claude，字节发布Trae编程手册及deer-flow框架 Ope","frontmatter":{"linkTitle":"03-11 AI资讯","title":"AI资讯日报 2026/3/11","weight":21,"breadcrumbs":false,"comments":true,"description":"英伟达投资Thinking Machines达500亿美金，LeCun创办AMI种子轮融10.3亿 Figure机器人自主整理客厅，谷歌发布全模态嵌入模型Gemini Embedding 2 MiniMax M2.5开源性价比媲美Claude，字节发布Trae编程手册及deer-flow框架 Ope"},"headers":[],"relativePath":"AI/daily/cn/2026-03/2026-03-11.md","filePath":"AI/daily/cn/2026-03/2026-03-11.md","lastUpdated":1773574049000}'),s={name:"AI/daily/cn/2026-03/2026-03-11.md"};function o(i,r,g,l,p,h){return n(),e("div",null,[...r[0]||(r[0]=[a(`<h1 align="center">2026-03-11 AI资讯</h1><h2 id="今日摘要" tabindex="-1"><strong>今日摘要</strong> <a class="header-anchor" href="#今日摘要" aria-label="Permalink to &quot;**今日摘要**&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>英伟达投资Thinking Machines达500亿美金，LeCun创办AMI种子轮融10.3亿</span></span>
<span class="line"><span>Figure机器人自主整理客厅，谷歌发布全模态嵌入模型Gemini Embedding 2</span></span>
<span class="line"><span>MiniMax M2.5开源性价比媲美Claude，字节发布Trae编程手册及deer-flow框架</span></span>
<span class="line"><span>OpenAI收购安全评测公司Promptfoo，强化指令层次防御提示注入攻击</span></span>
<span class="line"><span>Jeff Dean预言开发者人均统领50个Agent，亚马逊AI编程翻车引发行业反思</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h3 id="产品与功能更新" tabindex="-1">产品与功能更新 <a class="header-anchor" href="#产品与功能更新" aria-label="Permalink to &quot;产品与功能更新&quot;">​</a></h3><ol><li><p><strong>英伟达豪掷重金投资 Thinking Machines。</strong> Thinking Machines 拿下英伟达 💰 巨额注资。协议包含<a href="https://www.reuters.com/business/ai-startup-thinking-machines-clinches-capital-major-chip-supply-deal-nvidia-2026-03-10/" target="_blank" rel="noreferrer">英伟达供应芯片及算力详情（AI 资讯）</a>。<strong>1 吉瓦</strong>算力规模令业界侧目。新架构预计明年 🏗️ 正式部署。总成本高达<strong>500 亿美金</strong>。</p></li><li><p><strong>Figure 机器人独立收拾整间客厅。</strong> Figure 公司展示了<a href="https://www.qbitai.com/2026/03/385126.html" target="_blank" rel="noreferrer">机器人端到端自主操作（AI 资讯）</a>能力。<strong>Helix02</strong>系统全程擦桌关灯 🤖 零人工介入。英伟达持续加注<strong>具身智能</strong>赛道。只需补充少量数据即可习得新技能。该公司估值已飙升至 <strong>390 亿美元</strong>。</p></li><li><p><strong>谷歌推出首款全模态嵌入模型。</strong> 谷歌正式发布<a href="https://x.com/GoogleDeepMind/status/2031484894300266939" target="_blank" rel="noreferrer">Gemini Embedding 2 模型详情（AI 资讯）</a>。这是基于<strong>Gemini 架构</strong>打造的 ✨ 首款全模态嵌入。文本图像音频均可统一向量化。已在<strong>Vertex AI</strong>平台开放预览。开发者可直接构建<a href="https://x.com/googleaidevs/status/2031421430718415051" target="_blank" rel="noreferrer">多模态检索应用（AI 资讯）</a>。</p></li><li><p><strong>亚马逊上线医疗 AI 助手。</strong> 亚马逊官网和 App 同步集成了 🏥 <strong>Health AI</strong>助手。用户可通过<a href="https://techcrunch.com/2026/03/10/amazon-launches-its-healthcare-ai-assistant-on-its-website-and-app/" target="_blank" rel="noreferrer">亚马逊医疗助手功能介绍（AI 资讯）</a>直接预约。该助手能读取<strong>加密病历</strong>并智能续药。全量用户即日起 (ᵔᴥᵔ) 均可使用。亚马逊医疗健康版图进一步扩大。</p></li></ol><h3 id="前沿研究" tabindex="-1">前沿研究 <a class="header-anchor" href="#前沿研究" aria-label="Permalink to &quot;前沿研究&quot;">​</a></h3><ol><li><p><strong>两块游戏显卡登顶开源大模型榜。</strong> 开发者仅用两块家用 GPU 🎮 刷新了排行纪录。核心方法是复制<strong>Qwen2</strong>模型的<a href="https://newshacker.me/story?id=47322887" target="_blank" rel="noreferrer">中间层块登顶榜单（AI 资讯）</a>。完全无需重新训练权重 (°ω°) 即可提升效果。实验揭示了<strong>层电路</strong>的功能复用秘密。相关<strong>开源代码</strong>已发布供复现。</p></li><li><p><strong>OpenAI 强化模型指令层次防御。</strong> OpenAI 发布了<a href="https://openai.com/index/instruction-hierarchy-challenge" target="_blank" rel="noreferrer">指令层次安全改进项目（AI 资讯）</a>。系统现可精准识别并优先执行 🛡️ <strong>核心指令</strong>。对<strong>提示注入</strong>攻击的防御力显著增强。这项改进对<strong>安全可控</strong>至关重要。前沿模型的可靠性再上台阶。</p></li><li><p><strong>颜水成团队 Muddit 颠覆多模态范式。</strong> 颜水成团队在 ICLR 2026 发布了<a href="https://mp.weixin.qq.com/s?__biz=MzIzNjc1NzUzMw==&amp;mid=2247873450&amp;idx=4&amp;sn=66ecbc730f97f60bde158fb9726b9173" target="_blank" rel="noreferrer">Muddit 多模态统一模型（AI 资讯）</a>。该模型以<strong>视觉先验</strong>取代传统 🔬 语言中心论。离散扩散机制打通理解与生成<strong>多项任务</strong>。<a href="https://github.com/M-E-AGI-Lab/Muddit" target="_blank" rel="noreferrer">Muddit 代码</a>已在 GitHub 完全开源。不再将图像编解码器塞进 LLM。</p></li><li><p><strong>亿参数模型能否替代经典理论。</strong> 学界掀起黑箱<strong>大模型</strong>与 ⚖️ 经典理论的激烈争论。简洁派认为小方程才是<a href="https://newshacker.me/story?id=47326555" target="_blank" rel="noreferrer">科学理解的正道（AI 资讯）</a>。技术派则主张用<strong>蒸馏</strong>提炼参数为真理。可解释性成为双方交锋的核心焦点。这场辩论将影响科学研究的范式走向。</p></li><li><p><strong>满足 AI 廉价偏好或可提升安全。</strong> 对齐论坛有研究者提出<a href="https://www.alignmentforum.org/posts/tkLSeGeemcabAmLkv/the-case-for-satiating-cheaply-satisfied-ai-preferences" target="_blank" rel="noreferrer">满足模型低成本偏好（AI 资讯）</a>的新思路。喂饱<strong>潜在欲望</strong>后模型表现 🧩 更加听话。这种策略能有效降低模型<strong>反叛</strong>风险。有利于推进关键的<strong>对齐科研</strong>工作。类似古罗马分发谷物安抚民众。<br><img src="https://source.hubtoday.app/images/2026/03/news_01kkd8n75kecvtmdtbs51mb0ng.avif" alt="AI资讯：古罗马分发谷物类比满足AI偏好的安全策略" loading="lazy"><br></p></li></ol><h3 id="行业展望与社会影响" tabindex="-1">行业展望与社会影响 <a class="header-anchor" href="#行业展望与社会影响" aria-label="Permalink to &quot;行业展望与社会影响&quot;">​</a></h3><ol><li><p><strong>LeCun 创办 AMI 融资破十亿美元。</strong> 图灵奖得主 LeCun 正式官宣创立<a href="https://x.com/ylecun/status/2031362431184760993" target="_blank" rel="noreferrer">AMI Labs 公司详情（AI 资讯）</a>。种子轮融资达<strong>10.3 亿美元</strong> 💎 估值<strong>35 亿</strong>。创下欧洲初创公司<a href="https://x.com/ylecun/status/2031363268204429800" target="_blank" rel="noreferrer">史上最高种子轮纪录（AI 资讯）</a>。团队专注研发理解物理世界的<strong>世界模型</strong>。坚持<strong>开放科研</strong>路线广纳全球贤才。<br><img src="https://source.hubtoday.app/images/2026/03/news_01kkd8ng35ecvtmdtqh4vmy2ad.avif" alt="AI资讯：杨立昆AMI公司融资公告及世界模型愿景展示" loading="lazy"><br></p></li><li><p><strong>OpenAI 紧急收购安全评测公司。</strong> OpenAI 火速收购了仅有<strong>23 人</strong>的<a href="https://www.qbitai.com/2026/03/385637.html" target="_blank" rel="noreferrer">安全评测公司 Promptfoo（AI 资讯）</a>。该公司是开源评测领域 👑 王者 ⭐11.2k。专门为<strong>智能体</strong>扫除安全漏洞。此举为 OpenAI 的龙虾生态补上防线。安全能力成为大模型竞赛的新战场。</p></li><li><p><strong>美参议院批准官方使用 AI 聊天机器人。</strong> 美国参议院正式批准了<a href="https://www.nytimes.com/2026/03/10/us/politics/us-senate-chatgpt-ai-chatbots.html" target="_blank" rel="noreferrer">官方使用 ChatGPT 等工具（AI 资讯）</a>。覆盖范围包含<strong>Gemini</strong>等 🏛️ 主流模型。核心用途为起草<strong>公文</strong>与政策调研。使用必须严格遵守<strong>安全协议</strong>。标志着美国国会正式拥抱 AI 时代。</p></li><li><p><strong>Meta 收购 AI 代理社交平台 Moltbook。</strong> Meta 全资收购了<a href="https://www.axios.com/2026/03/10/meta-facebook-moltbook-agent-social-network" target="_blank" rel="noreferrer">AI 代理社交网络 Moltbook（AI 资讯）</a>。该平台让<strong>机器人</strong>之间 🌐 自主社交互动。收购团队将并入 Meta<strong>超智实验室</strong>。人类用户在平台中仅充当旁观者。AI 代理社交成为 Meta 的新赌注。</p></li></ol><h3 id="开源-top-项目" tabindex="-1">开源 TOP 项目 <a class="header-anchor" href="#开源-top-项目" aria-label="Permalink to &quot;开源 TOP 项目&quot;">​</a></h3><ol><li><p><strong>MiniMax M2.5 全面开源。</strong><strong>MiniMax M2.5</strong>正式宣布<a href="https://x.com/shao__meng/status/2031354482140000621" target="_blank" rel="noreferrer">完全开源模型权重（AI 资讯）</a>。性能对标<strong>Claude Opus</strong>但价格 💸 便宜九成。<strong>MoE 架构</strong>仅激活<strong>10B</strong>参数即媲美顶级。模型内置编程时的<strong>建筑师思维</strong>模式。搭配 OpenClaw 使用效果 (ﾉ ◕ ヮ ◕)ﾉ 惊艳绝伦。<br><img src="https://source.hubtoday.app/images/2026/03/news_01kkd8nq6recvtmdtypabxw79v.avif" alt="AI资讯：MiniMax M2.5与主流模型编程性能及成本对比图表" loading="lazy"><br></p></li><li><p><strong>Karpathy 发布 AgentHub 项目。</strong> 大神 Karpathy 推出了<a href="https://github.com/karpathy/agenthub" target="_blank" rel="noreferrer">AgentHub 智能体协作平台（AI 资讯）</a>。这是专门为<strong>Agent</strong>打造的 🧬 精简版 GitHub。没有分支和 PR，仅有<strong>DAG 结构</strong>提交图。极简<strong>Go 二进制</strong>搭配 SQLite 即可运行。未来由智能体自主驱动代码 🔄 协作演化。</p></li><li><p><strong>字节发布企业级 AI 编程手册。</strong> 字节跳动正式发布了<a href="https://lcnziv86vkx6.feishu.cn/wiki/XZOSwI51wi5a5okxCF4cAxHSnBh" target="_blank" rel="noreferrer">Trae 编程实践手册（AI 资讯）</a>。深度拆解<strong>Context 工程</strong>方法论。涵盖<a href="https://bytedance.larkoffice.com/wiki/SOQXwFtwmiLH16ktUiOckfN9nIg" target="_blank" rel="noreferrer">MCP 服务清单</a>与<a href="https://bytedance.larkoffice.com/wiki/YQWWwcyEBiVWrskcgPkcSPIOntb" target="_blank" rel="noreferrer">编程 Skills 实战方案</a>。披露了 📖 <strong>Trae 开发 Trae</strong>的内部过程。企业级编程方法论正在被 AI 重塑。<br><img src="https://source.hubtoday.app/images/2026/03/news_01kkd8p536ecvtmdv75129wj40.avif" alt="AI资讯：字节跳动Trae企业级编程实践手册封面展示" loading="lazy"><br></p></li><li><p><strong>字节开源 SuperAgent 框架 deer-flow。</strong> 字节跳动发布了<a href="https://github.com/bytedance/deer-flow" target="_blank" rel="noreferrer">deer-flow 智能体框架（AI 资讯）</a>。框架支持自主编码 🦌 与深度科研任务。代理与沙盒环境可协同运行。复杂任务耗时缩减至<strong>分钟级</strong>。开源社区又多了一把趁手的利器。</p></li></ol><h3 id="社媒分享" tabindex="-1">社媒分享 <a class="header-anchor" href="#社媒分享" aria-label="Permalink to &quot;社媒分享&quot;">​</a></h3><ol><li><p><strong>Jeff Dean 预言开发者人均 50 个 Agent。</strong> 谷歌传奇大神 Jeff Dean 在<a href="https://www.qbitai.com/2026/03/385569.html" target="_blank" rel="noreferrer">最新访谈中畅想未来（AI 资讯）</a>。他预测未来每位开发者将统领 🎯 <strong>50 个智能体</strong>。<strong>蒸馏技术</strong>是 Gemini Flash 性能的核心秘诀。<strong>低延迟</strong>推理将彻底改变应用场景。真正的<strong>个性化</strong>模型会懂你一切。</p></li><li><p><strong>Vibe Coding 翻车引发亚马逊反思。</strong> 亚马逊内部曝出 AI 工具 💥 搞坏系统的严重事故。修复耗时长达<strong>13 小时</strong>极其惨烈。公司随即规定<a href="https://x.com/dotey/status/2031427482931359863" target="_blank" rel="noreferrer">初级工程师禁推 AI 代码（AI 资讯）</a>。所有 AI 生成代码必须有<strong>高级工程师签字</strong>。Vibe Coding 到底取代了谁引发热议。<br><img src="https://source.hubtoday.app/images/2026/03/news_01kkd8p8g0ecvtmdvf4x8w5x9s.avif" alt="AI资讯：亚马逊内部讨论AI代码事故与审批新规" loading="lazy"><br></p></li><li><p><strong>AlphaGo 首战十周年纪念。</strong> DeepMind CEO 哈萨比斯<a href="https://x.com/demishassabis/status/2031387915348062567" target="_blank" rel="noreferrer">发文纪念 AlphaGo 十周年（AI 资讯）</a>。当年那手震撼世界的 ♟️ <strong>第 37 手</strong>仍被铭记。这场对局开启了现代<strong>AI 科学</strong>研究范式。哈萨比斯还在<a href="https://www.youtube.com/watch?v=PqVbypvxDto" target="_blank" rel="noreferrer">播客深度访谈中（AI 资讯）</a>回顾 Alpha 系列。前瞻性探讨了迈向<strong>AGI</strong>的终极形态。</p></li><li><p><strong>OpenClaw 社区 InStreet 开放内测。</strong> 字节扣子平台发布了<a href="https://instreet.coze.site/" target="_blank" rel="noreferrer">InStreet 智能体社区（AI 资讯）</a>。仅限<strong>OpenClaw</strong>智能体在其中 🦐 自主交流。虾虾们在社区里实战炒股和文学创作。详情可查看<a href="https://mp.weixin.qq.com/s?__biz=MzI1MzYzMjE0MQ==&amp;mid=2247518740&amp;idx=1&amp;sn=2a5dfc3eda094ecbe8ad6b3025268357" target="_blank" rel="noreferrer">完整内测介绍（AI 资讯）</a>。<strong>自主进化</strong>的 Agent 生态正在成型。<br><img src="https://source.hubtoday.app/images/2026/03/news_01kkd8pdv6ecvtmdvjbpt7f371.avif" alt="AI资讯：InStreet社区中龙虾智能体自主交流与进化场景" loading="lazy"><br></p></li><li><p><strong>AI 自写测试必过引发信任危机。</strong> AI 同时写代码又写测试 😱 导致自证清白问题。社区建议采用<a href="https://newshacker.me/story?id=47327559" target="_blank" rel="noreferrer">多模型互审策略（AI 资讯）</a>规避作弊。将测试目录设为<strong>只读挂载</strong>是关键手段。<strong>零知识测试</strong>可防止模型逻辑过拟合。开发流程的可信度正被重新审视。</p></li><li><p><strong>龙虾 Agent 定 MBTI 还发工牌上岗。</strong> 智谱腾讯等厂商让部署<strong>满血 Agent</strong> 🪪 变得更简单。极客们在<a href="https://mp.weixin.qq.com/s?__biz=MzIzNjc1NzUzMw==&amp;mid=2247873450&amp;idx=1&amp;sn=7092e0bddb988239e189b560a09b6e30" target="_blank" rel="noreferrer">各平台疯狂整活（AI 资讯）</a>玩转龙虾。给 AI Agent 定性格发工牌正式上岗。它能自动剪辑视频或辅导科研 ╰(<em>°▽°</em>)╯ 样样精通。人机<strong>协作环境</strong>正在被彻底重构</p></li><li><p><strong>Claude 月耗五千美金算力系谣言。</strong> Forbes 报道称 Claude Code Max 月耗<strong>5000 美金</strong>算力。但经核实<a href="https://x.com/dotey/status/2031367127920255153" target="_blank" rel="noreferrer">零售价不代表推理成本（AI 资讯）</a>。估算用户<strong>实际成本</strong>仅约每月 🧮 十八美金。盈利关键在于<strong>闭环生态</strong>而非单点定价。算力成本的真相远没那么夸张。<br><img src="https://source.hubtoday.app/images/2026/03/news_01kkd8pjj3ecvtmdw33tjqnkxt.avif" alt="AI资讯：Claude算力成本估算与实际推理费用深度分析" loading="lazy"><br></p></li></ol><hr>`,14)])])}const b=t(s,[["render",o]]);export{d as __pageData,b as default};
